#include "lvgl.h"
#include "ui_common.h"

/* Pre-rendered Montserrat-Medium bitmap fonts (4 bpp, Latin-1 + typographic
 * punctuation, no kerning), generated by fonts/gen_fonts.sh. No glyph is
 * rasterised at run time. LV_SYMBOL_* glyphs (FontAwesome) are not part of the
 * generated fonts; gen_fonts.sh sets the built-in LVGL Montserrat as .fallback. */
extern const lv_font_t ui_font_montserrat_12;
extern const lv_font_t ui_font_montserrat_14;
extern const lv_font_t ui_font_montserrat_20;
extern const lv_font_t ui_font_montserrat_28;

const lv_font_t *ui_f12;
const lv_font_t *ui_f14;
const lv_font_t *ui_f20;
const lv_font_t *ui_f28;

void ui_fonts_init(void)
{
    ui_f12 = &ui_font_montserrat_12;
    ui_f14 = &ui_font_montserrat_14;
    ui_f20 = &ui_font_montserrat_20;
    ui_f28 = &ui_font_montserrat_28;
}
